def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    comps = []
    while cells:
        start = cells.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p)
                    comp.add(p)
                    q.append(p)
        comps.append(comp)

    # The largest component is the multicolored template; isolated cells are placement markers.
    template_comp = max(comps, key=len)
    marker_color = next(iter(set(x for row in grid for x in row) - {bg} - {grid[r][c] for r,c in template_comp}), None)
    if marker_color is None:
        marker_color = min((grid[r][c] for r,c in template_comp), key=lambda x: sum(v == x for row in grid for v in row))

    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker_color and (r,c) not in template_comp]
    r0 = min(r for r,c in template_comp); r1 = max(r for r,c in template_comp)
    c0 = min(c for r,c in template_comp); c1 = max(c for r,c in template_comp)
    ar, ac = (r0+r1)//2, (c0+c1)//2

    out = [row[:] for row in grid]
    for r,c in markers:
        for tr,tc in template_comp:
            rr, cc = r + tr-ar, c + tc-ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[tr][tc]
    return out
